
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_qtp17_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_qtp17", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.659143700811626e+00, -1.626932664111776e+00, -1.581774697658248e+00, -1.519172302929073e+00, -1.433768484954305e+00, -1.319890546760854e+00, -1.172871491700688e+00, -9.914618307813300e-01, -7.813020124288994e-01, -5.593240934527310e-01, -3.670979190881601e-01, -2.949642022808395e-01, -2.652714411448457e-01, -2.158498092028307e-01, -1.485485331914117e-01, -8.027385038772132e-02, -3.350331981884764e-02, -1.489716160455456e-02, -3.789347965008842e-03, -5.416778077796013e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


